// Camisas retrô (usam as cores do time invertidas)
const RETRO = "Flamengo;Palmeiras;Corinthians;São Paulo;Santos;Vasco;Grêmio;Cruzeiro;Internacional;River Plate;Boca Juniors;Juventus;Milan;Inter de Milão;Fiorentina;Betis;Real Madrid;Barcelona;Manchester United;Manchester City;Chelsea;Liverpool;Arsenal;Bayern de Munique;Brasil;Argentina;Espanha;Itália;Inglaterra;Holanda".split(";");

const CATEGORIAS = ["Brasileirão Série A", "Brasileirão Série B", "Times do Mundo", "Seleções", "NBA", "NFL", "Retrô"];
const GRUPOS = [["Brasileirão Série A", T.A, "camisa"], ["Brasileirão Série B", T.B, "camisa"], ["Times do Mundo", T.M, "camisa"], ["Seleções", T.S, "camisa"], ["NBA", T.NBA, "regata"], ["NFL", T.NFL, "camisa"]];

// ---- MONTAGEM DOS 180 PRODUTOS ----
const slug = (s) => s.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
const parse = (s) => s.split(";").map(t => t.split(":"));
const COR = {}; GRUPOS.forEach(([c, l]) => parse(l).forEach(([n, a, b]) => COR[n] = [a, b]));
const SELECOES = new Set(parse(T.S).map(x => x[0]));
const ALIAS = { "Coreia do Sul": "Coreia" };
const escudo = (nome, grupo) => IMGS[grupo + "-" + slug(ALIAS[nome] || nome)] || null;
// Nomes personalizados (a chave é o nome padrão em minúsculo com hífens)
const NOMES = {
  "camisa-chelsea-atual": "CAMISA I CHELSEA 26/27 NIKE",
  "camisa-chelsea-atual-ii": "CAMISA II CHELSEA 26/27 NIKE",
  "camisa-barcelona-atual": "CAMISA II BARCELONA 26/27 NIKE",
  "camisa-bayern-de-munique-atual": "CAMISA I BAYERN 26/27 ADIDAS",
  "camisa-manchester-city-atual": "CAMISA II MAN. CITY 26/27 PUMA",
  "camisa-napoli-atual": "CAMISA I NAPOLI 26/26 EA7",
  "camisa-milan-atual": "CAMISA II MILAN 26/27 PUMA",
  "camisa-lyon-atual": "CAMISA II LYON 26/27 ADIDAS",
  "camisa-psg-atual": "CAMISA I PSG 26/27 NIKE"
};
const PRODUTOS = [];
let _id = 0;
const add = (cat, n, forma, tag, retro) => {
  const [a, b] = COR[n];
  const grupo = cat === "NBA" ? "nba" : (SELECOES.has(n) ? "sel" : "clube");
  const pre = cat === "NBA" ? "Regata NBA" : cat === "NFL" ? "Camisa NFL" : "Camisa";
  const nomePadrao = `${pre} ${n} - ${tag}`;
  const nome = NOMES[slug(nomePadrao)] || nomePadrao;
  PRODUTOS.push({ id: ++_id, key: slug(nomePadrao), cat, nome, tag, forma, retro, time: n, preco: PRECO, sigla: n.replace(/[^A-Za-zÀ-ú ]/g, "").split(" ").map(w => w[0]).join("").slice(0, 3).toUpperCase(),
    c1: "#" + (retro ? b : a), c2: "#" + (retro ? a : b), escudo: escudo(n, grupo) });
};
GRUPOS.forEach(([cat, lista, forma]) => parse(lista).forEach(([n]) => add(cat, n, forma, "Atual", false)));
add("Times do Mundo", "Chelsea", "camisa", "Atual II", false); // 2º uniforme do Chelsea
RETRO.forEach(n => add("Retrô", n, "camisa", "Retrô", true));

const TAMANHOS = ["P", "M", "G", "GG"];

// ---- UTILIDADES ----
const $ = (s) => document.querySelector(s);
const brl = (v) => v.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
const toast = (msg) => { const t = $("#toast"); t.textContent = msg; t.classList.add("on"); setTimeout(() => t.classList.remove("on"), 1800); };
function camisaSVG(p) {
  const tank = p.forma === "regata";
  const corpo = tank ? "M70 10 L70 60 L44 110 L44 196 L156 196 L156 110 L130 60 L130 10 C118 40 82 40 70 10Z"
                     : "M60 12 L20 38 L4 82 L36 96 L44 76 L44 196 L156 196 L156 76 L164 96 L196 82 L180 38 L140 12 C130 30 70 30 60 12Z";
  const detalhes = tank
    ? `<path d="M70 10 C82 40 118 40 130 10" fill="none" stroke="${p.c2}" stroke-width="6"/><path d="M44 110 L70 60 M156 110 L130 60" stroke="${p.c2}" stroke-width="5"/>`
    : `<path d="M60 12 C70 30 130 30 140 12" fill="none" stroke="${p.c2}" stroke-width="6"/><path d="M4 82 L36 96 M196 82 L164 96" stroke="${p.c2}" stroke-width="7"/>`;
  const faixa = p.retro ? `<rect x="44" y="120" width="112" height="12" fill="${p.c2}" opacity=".85"/><rect x="44" y="138" width="112" height="5" fill="${p.c2}" opacity=".6"/>` : `<rect x="44" y="150" width="112" height="46" fill="${p.c2}" opacity=".12"/>`;
  const num = tank || p.cat === "NFL" ? `<text x="100" y="125" text-anchor="middle" font-family="Montserrat,Arial" font-weight="800" font-size="46" fill="${p.c2}">${(p.id % 23) + 1}</text>` : `<text x="128" y="78" text-anchor="middle" font-family="Montserrat,Arial" font-weight="800" font-size="13" fill="${p.c2}">${p.sigla}</text>`;
  return `<svg viewBox="0 0 200 210" aria-hidden="true"><ellipse cx="100" cy="203" rx="62" ry="5" fill="#000" opacity=".1"/><path d="${corpo}" fill="${p.c1}" stroke="rgba(0,0,0,.3)" stroke-width="2" stroke-linejoin="round"/>${faixa}${detalhes}${num}</svg>`;
}

// ---- ESTADO ----
let filtro = "Todos";
let carrinho = [];
try { carrinho = JSON.parse(localStorage.getItem("ph-carrinho3")) || []; } catch (e) { carrinho = []; }
const salvar = () => { try { localStorage.setItem("ph-carrinho3", JSON.stringify(carrinho)); } catch (e) {} };
const tamanhoEscolhido = {};
const fotoAtual = {};
let vis = 24;

// ---- LOJA ----
function renderChips() {
  $("#chips").innerHTML = ["Todos", ...CATEGORIAS].map(c => `<button class="chip ${c === filtro ? "on" : ""}" data-c="${c}">${c}</button>`).join("");
}
function renderProdutos() {
  const q = $("#search").value.trim().toLowerCase();
  const ordem = $("#sort").value;
  let lista = PRODUTOS.filter(p => (filtro === "Todos" || p.cat === filtro) && (p.nome + " " + p.cat).toLowerCase().includes(q));
  if (ordem) lista.sort((a, b) => ordem === "asc" ? a.preco - b.preco : b.preco - a.preco);
  const total = lista.length;
  $("#resultado").textContent = total + (total === 1 ? " produto" : " produtos");
  lista = lista.slice(0, vis);
  const antigo = PORCENTAGEM_OFF > 0 ? PRECO / (1 - PORCENTAGEM_OFF / 100) : 0;
  $("#grid").innerHTML = total ? lista.map(p => {
    const fotos = [].concat(FOTOS[p.key] || []);
    const fi = Math.min(fotoAtual[p.id] || 0, fotos.length - 1);
    return `
    <article class="card">
      <div class="thumb ${fotos.length ? "com-foto" : ""}" ${fotos.length ? `data-lb="${p.id}"` : ""}>
        ${p.tag === "Retrô" ? `<span class="tag">Retrô</span>` : ""}
        ${fotos.length ? `<img class="foto" src="${fotos[fi]}" alt="${p.nome}" loading="lazy">` : camisaSVG(p)}
        ${p.escudo && !fotos.length ? `<img class="badge" src="${p.escudo}" alt="" loading="lazy">` : ""}
        ${fotos.length ? `<span class="lupa">🔍 Ampliar</span>` : ""}
      </div>
      ${fotos.length > 1 ? `<div class="mini">${fotos.map((f, i) => `<button class="mini-b ${i === fi ? "on" : ""}" data-foto="${p.id}:${i}" aria-label="Foto ${i + 1}"><img src="${f}" alt=""></button>`).join("")}</div>` : ""}
      ${PORCENTAGEM_OFF > 0 ? `<div class="off">-${PORCENTAGEM_OFF}% OFF</div>` : ""}
      <div class="info">
        <h3>${p.nome}</h3>
        <small>${p.cat}</small>
        ${antigo ? `<s>${brl(antigo)}</s>` : ""}
        <div class="price">${brl(p.preco)} <span>no Pix</span></div>
        ${PARCELAS ? `<div class="parc">ou ${PARCELAS}x de ${brl(p.preco / PARCELAS)} sem juros</div>` : ""}
        <div class="sizes">${TAMANHOS.map(t => `<button class="sz ${tamanhoEscolhido[p.id] === t ? "on" : ""}" data-id="${p.id}" data-t="${t}">${t}</button>`).join("")}</div>
        <button class="btn" data-add="${p.id}">Adicionar ao carrinho</button>
      </div>
    </article>`; }).join("") + (total > vis ? `<button class="btn ghost more" data-more="1">Ver mais (${total - vis} restantes)</button>` : "") : `<p class="empty">Nenhum produto encontrado.</p>`;
}
const filtrar = (c) => { filtro = c; vis = 24; renderChips(); renderProdutos(); };
$("#chips").addEventListener("click", e => { if (e.target.dataset.c) filtrar(e.target.dataset.c); });
$("#subnav").addEventListener("click", e => { const c = e.target.dataset.c; if (c) { filtrar(c); $("#loja").scrollIntoView({ behavior: "smooth" }); } });
$("#search").addEventListener("input", () => { vis = 24; renderProdutos(); });
$("#sort").addEventListener("change", () => { vis = 24; renderProdutos(); });
$("#grid").addEventListener("click", e => {
  const t = e.target;
  const fb = t.closest("[data-foto]");
  if (fb) { const [id, i] = fb.dataset.foto.split(":"); fotoAtual[id] = +i; renderProdutos(); return; }
  const lbEl = t.closest("[data-lb]");
  if (lbEl) { abrirLb(+lbEl.dataset.lb); return; }
  if (t.dataset.more) { vis += 24; renderProdutos(); return; }
  if (t.dataset.t) { tamanhoEscolhido[t.dataset.id] = t.dataset.t; renderProdutos(); return; }
  if (t.dataset.add) {
    const p = PRODUTOS.find(x => x.id == t.dataset.add);
    const tam = tamanhoEscolhido[p.id];
    if (!tam) { toast("Escolha um tamanho"); return; }
    const item = carrinho.find(i => i.id === p.id && i.tam === tam);
    item ? item.qtd++ : carrinho.push({ id: p.id, tam, qtd: 1 });
    salvar(); renderCarrinho(); toast("Adicionado ao carrinho");
  }
});

// ---- CARRINHO ----
function renderCarrinho() {
  let total = 0, qtd = 0;
  $("#items").innerHTML = carrinho.length ? carrinho.map((i, idx) => {
    const p = PRODUTOS.find(x => x.id === i.id); total += p.preco * i.qtd; qtd += i.qtd;
    return `<div class="line"><div><b>${p.nome}</b><br><small>Tamanho: ${i.tam}</small>
      <div class="qty"><button data-m="${idx}">−</button>${i.qtd}<button data-p="${idx}">+</button></div></div>
      <div style="text-align:right"><b>${brl(p.preco * i.qtd)}</b><br><button class="rm" data-r="${idx}">Remover</button></div></div>`;
  }).join("") : `<p class="empty">Seu carrinho está vazio.</p>`;
  $("#total").textContent = brl(total);
  $("#count").textContent = qtd;
}
$("#items").addEventListener("click", e => {
  const d = e.target.dataset;
  if (d.p !== undefined) carrinho[d.p].qtd++;
  if (d.m !== undefined) { carrinho[d.m].qtd--; if (carrinho[d.m].qtd <= 0) carrinho.splice(d.m, 1); }
  if (d.r !== undefined) carrinho.splice(d.r, 1);
  salvar(); renderCarrinho();
});
$("#clear").addEventListener("click", () => { carrinho = []; salvar(); renderCarrinho(); });
const abrir = (v) => { $("#drawer").classList.toggle("on", v); $("#overlay").classList.toggle("on", v); };
$("#openCart").addEventListener("click", () => abrir(true));
$("#closeCart").addEventListener("click", () => abrir(false));
$("#overlay").addEventListener("click", () => abrir(false));

// ---- PEDIDO PELO WHATSAPP ----
$("#checkout").addEventListener("click", () => {
  if (!carrinho.length) { toast("Carrinho vazio"); return; }
  let total = 0;
  const linhas = carrinho.map(i => {
    const p = PRODUTOS.find(x => x.id === i.id); total += p.preco * i.qtd;
    return `• ${i.qtd}x ${p.nome} (${i.tam}) - ${brl(p.preco * i.qtd)}`;
  });
  const nome = $("#cliente").value.trim();
  const msg = `Olá, PH IMPORTS! Quero fazer um pedido${nome ? " (" + nome + ")" : ""}:\n\n${linhas.join("\n")}\n\nTotal: ${brl(total)}`;
  window.open(`https://wa.me/${WHATSAPP}?text=${encodeURIComponent(msg)}`, "_blank");
});
$("#contactForm").addEventListener("submit", e => {
  e.preventDefault();
  const f = new FormData(e.target);
  const msg = `Olá, PH IMPORTS! Sou ${f.get("nome")} (${f.get("email")}).\n\n${f.get("msg")}`;
  window.open(`https://wa.me/${WHATSAPP}?text=${encodeURIComponent(msg)}`, "_blank");
});

// ---- MENU E INÍCIO ----
$("#year").textContent = new Date().getFullYear();
// ---- GALERIA COM ZOOM (clique na foto) ----
let lbFotos = [], lbI = 0, lbZ = 1, lbTitulo = "";
const lbImg = $("#lbImg"), lbStage = $("#lbStage");
function lbZoom(z) {
  lbZ = Math.max(1, Math.min(4, z));
  lbImg.style.transform = `scale(${lbZ})`;
  if (lbZ === 1) lbImg.style.transformOrigin = "50% 50%";
  lbImg.classList.toggle("zoomed", lbZ > 1);
  $("#lbPct").textContent = Math.round(lbZ * 100) + "%";
}
function lbRender() {
  lbImg.src = lbFotos[lbI]; lbImg.alt = lbTitulo; lbZoom(1);
  $("#lbTitle").textContent = lbTitulo + (lbFotos.length > 1 ? `  (${lbI + 1}/${lbFotos.length})` : "");
  $("#lbThumbs").innerHTML = lbFotos.length > 1 ? lbFotos.map((f, i) => `<button class="mini-b ${i === lbI ? "on" : ""}" data-i="${i}" aria-label="Foto ${i + 1}"><img src="${f}" alt=""></button>`).join("") : "";
  $("#lbPrev").style.display = $("#lbNext").style.display = lbFotos.length > 1 ? "" : "none";
}
function abrirLb(id) {
  const p = PRODUTOS.find(x => x.id === id);
  lbFotos = [].concat(FOTOS[p.key] || []); lbI = Math.min(fotoAtual[id] || 0, lbFotos.length - 1); lbTitulo = p.nome;
  lbRender(); $("#lb").classList.add("on"); document.body.style.overflow = "hidden";
}
function fecharLb() { $("#lb").classList.remove("on"); document.body.style.overflow = ""; if (lbFotos.length) { /* mantém a foto escolhida no card */ const p = PRODUTOS.find(x => x.nome === lbTitulo); if (p) { fotoAtual[p.id] = lbI; renderProdutos(); } } }
const lbIr = (d) => { lbI = (lbI + d + lbFotos.length) % lbFotos.length; lbRender(); };
const lbOrigem = (cx, cy) => { // o zoom acompanha o mouse/dedo, como na Netshoes
  const s = lbStage.getBoundingClientRect();
  const x = Math.max(0, Math.min(100, (cx - s.left - lbImg.offsetLeft) / lbImg.offsetWidth * 100));
  const y = Math.max(0, Math.min(100, (cy - s.top - lbImg.offsetTop) / lbImg.offsetHeight * 100));
  lbImg.style.transformOrigin = `${x}% ${y}%`;
};
$("#lbX").addEventListener("click", fecharLb);
$("#lbPrev").addEventListener("click", () => lbIr(-1));
$("#lbNext").addEventListener("click", () => lbIr(1));
$("#lbPlus").addEventListener("click", () => lbZoom(lbZ + 0.75));
$("#lbMinus").addEventListener("click", () => lbZoom(lbZ - 0.75));
$("#lbThumbs").addEventListener("click", e => { const b = e.target.closest("[data-i]"); if (b) { lbI = +b.dataset.i; lbRender(); } });
lbStage.addEventListener("click", e => { if (e.target === lbStage) { fecharLb(); return; } if (lbZ === 1) { lbOrigem(e.clientX, e.clientY); lbZoom(2.5); } else lbZoom(1); });
lbStage.addEventListener("mousemove", e => { if (lbZ > 1) lbOrigem(e.clientX, e.clientY); });
lbStage.addEventListener("touchmove", e => { if (lbZ > 1) { e.preventDefault(); lbOrigem(e.touches[0].clientX, e.touches[0].clientY); } }, { passive: false });
document.addEventListener("keydown", e => {
  if (!$("#lb").classList.contains("on")) return;
  if (e.key === "Escape") fecharLb();
  if (e.key === "ArrowLeft") lbIr(-1);
  if (e.key === "ArrowRight") lbIr(1);
  if (e.key === "+" || e.key === "=") lbZoom(lbZ + 0.75);
  if (e.key === "-") lbZoom(lbZ - 0.75);
});

// ---- MODO CLARO / ESCURO ----
let tema = "light";
try { tema = localStorage.getItem("ph-tema") || (matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light"); } catch (e) {}
const aplicarTema = (t) => { document.documentElement.dataset.tema = t; $("#tema").textContent = t === "dark" ? "☀️ Modo claro" : "🌙 Modo escuro"; };
aplicarTema(tema);
$("#tema").addEventListener("click", () => { tema = tema === "dark" ? "light" : "dark"; aplicarTema(tema); try { localStorage.setItem("ph-tema", tema); } catch (e) {} });

renderChips(); renderProdutos(); renderCarrinho();